from lib import *

# =============================== DB ===============================
S = 'db'
EMP = [('김', '개발', 300, 100), ('이', '개발', 400, None), ('박', '영업', 250, 200), ('최', '영업', 350, None), ('정', '인사', 200, 50)]
emp_tbl = table(['이름', '부서', '급여', '보너스'], [[n, d, s, 'NULL' if b is None else b] for n, d, s, b in EMP])
def grp(rows, key):
    g = {}
    for r in rows: g.setdefault(key(r), []).append(r)
    return g
g = grp(EMP, lambda r: r[1])
for th in (300, 250, 350):
    keep = [d for d, rs in g.items() if sum(r[2] for r in rs) / len(rs) >= th]
    add(S, 'SQL', '테이블 EMP가 다음과 같다.' + emp_tbl + '<code>SELECT 부서, AVG(급여) FROM EMP GROUP BY 부서 HAVING AVG(급여) &gt;= %d;</code>의 결과 행 수는?' % th,
        len(keep), [x for x in (1, 2, 3, 5, 0) if x != len(keep)][:3],
        ol('GROUP BY 부서 → 부서별로 묶는다' + table(['부서', '급여들', 'AVG(급여)'], [[d, ', '.join(str(r[2]) for r in rs), fmt(sum(r[2] for r in rs) / len(rs))] for d, rs in g.items()]),
           'HAVING은 <b>그룹</b>에 조건을 건다: 평균 ≥ %d → %s → <b>%d행</b>' % (th, ', '.join(keep) or '없음', len(keep)))
        + tip('실행 순서: FROM → WHERE(행 거르기) → GROUP BY → HAVING(그룹 거르기) → SELECT → ORDER BY. 집계 함수 조건은 WHERE에 쓸 수 없다.'))
add(S, 'SQL', 'EMP 테이블(위와 같음)에서 <code>SELECT COUNT(*), COUNT(보너스), AVG(보너스) FROM EMP;</code>의 결과는?' + emp_tbl, '5 / 3 / 116.67', ['5 / 5 / 70', '3 / 3 / 116.67', '5 / 3 / 70'],
    ol('COUNT(*)는 NULL과 상관없이 <b>행 수</b> → 5', 'COUNT(열)과 AVG(열)은 그 열이 NULL인 행을 <b>제외</b>한다 → 보너스 값 100, 200, 50 → COUNT 3',
       'AVG = (100 + 200 + 50) / 3 = 350 / 3 ≈ <b>116.67</b> (NULL을 0으로 치면 70이 되지만 그렇게 계산하지 않는다)')
    + tip('NULL과의 비교(= NULL)는 항상 참이 아니다 → IS NULL로 검사. NULL을 0처럼 쓰려면 COALESCE(보너스, 0).'))
add(S, 'SQL', 'DEPT(부서) = 개발, 영업, 인사, 총무이고 EMP는 위와 같다.<br><code>SELECT COUNT(*) FROM DEPT D LEFT OUTER JOIN EMP E ON D.부서 = E.부서;</code>의 결과는?' + emp_tbl, 6, [5, 4, 20],
    ol('조인 조건으로 짝을 짓는다: 개발 2명, 영업 2명, 인사 1명 → 5행', 'LEFT OUTER JOIN은 왼쪽(DEPT) 행을 <b>모두</b> 남긴다. 짝 없는 총무는 E 쪽 열이 NULL인 1행으로 나온다.', '5 + 1 = <b>6</b>')
    + table(['조인', '행 수'], [['INNER JOIN', '5'], ['LEFT OUTER JOIN', '6'], ['RIGHT OUTER JOIN (EMP 기준)', '5'], ['CROSS JOIN', '4 × 5 = 20']]))
add(S, 'SQL', 'EMP(위와 같음)에서 <code>SELECT 이름 FROM EMP WHERE 급여 &gt; (SELECT AVG(급여) FROM EMP);</code>의 결과 행 수는?' + emp_tbl, 2, [3, 1, 5],
    ol('서브쿼리 먼저: AVG(급여) = (300 + 400 + 250 + 350 + 200) / 5 = 1500 / 5 = <b>300</b>', '급여 > 300 → 이(400), 최(350) → <b>2행</b> (300은 같으므로 제외)')
    + tip('IN은 서브쿼리 결과 중 하나와 같으면 참, ANY(SOME)는 하나라도 만족, ALL은 모두 만족. 상관 서브쿼리는 바깥 행마다 다시 실행된다.'))
