S = 'sec'
for p, q, e, M in [(3, 11, 3, 4), (5, 11, 3, 2), (7, 11, 7, 3), (3, 17, 5, 2)]:
    n = p * q; phi = (p - 1) * (q - 1); d = pow(e, -1, phi); Cc = pow(M, e, n)
    k = (e * d - 1) // phi
    add(S, 'RSA', 'RSA에서 p = %d, q = %d, 공개 지수 e = %d일 때 개인 지수 d와 평문 M = %d의 암호문은?' % (p, q, e, M), 'd = %d, C = %d' % (d, Cc),
        ['d = %d, C = %d' % (phi - d, Cc), 'd = %d, C = %d' % (d, pow(M, d, n)), 'd = %d, C = %d' % (e, M ** e)],
        ol('n = p × q = %d, φ(n) = (p − 1)(q − 1) = %d × %d = <b>%d</b>' % (n, p - 1, q - 1, phi),
           'e × d ≡ 1 (mod %d)인 d 찾기: %d × %d = %d = %d × %d + 1 → <b>d = %d</b>' % (phi, e, d, e * d, k, phi, d),
           '암호화 C = M^e mod n = %d^%d mod %d = %d mod %d = <b>%d</b>' % (M, e, n, M ** e, n, Cc), '검산: 복호화 C^d mod n = %d^%d mod %d = %d ✓' % (Cc, d, n, pow(Cc, d, n)))
        + tip('공개키 (n, e), 개인키 (n, d). RSA의 안전성은 큰 수 n의 소인수분해가 어렵다는 데 있다.'))
